package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;import com.lianxibu.site.domain.identity.NodeTokens;import com.lianxibu.site.repository.identity.JdbcNodeStore;import com.lianxibu.site.repository.jobs.JdbcSharedWriteEntry;import com.lianxibu.site.service.identity.*;
import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import javax.sql.DataSource;import org.junit.jupiter.api.*;import org.springframework.jdbc.datasource.DataSourceTransactionManager;
class CollectorHeartbeatServiceTest {
 CollectorHeartbeatsNativeTest f;CollectorHeartbeatService service;NodeIdentityService identity;JdbcNodeStore nodes;String token;AtomicReference<Instant> at;Clock clock;
 DataSource source(){return new CollectorHeartbeatsNativeTest().source();}
 @BeforeEach void setup()throws Exception{f=new CollectorHeartbeatsNativeTest(){@Override DataSource source(){return CollectorHeartbeatServiceTest.this.source();}};f.setup();f.jdbc.execute("CREATE TABLE IF NOT EXISTS worker_lock(id INT PRIMARY KEY)");if(f.jdbc.queryForObject("SELECT COUNT(*) FROM worker_lock WHERE id=1",Integer.class)==0)f.jdbc.update("INSERT INTO worker_lock VALUES(1)");at=new AtomicReference<>(f.now);clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at.get();}};var tokens=new NodeTokens(new byte[32]);token=tokens.issue("fictional-owner","fictional-heartbeat","fictional-key",f.node);f.jdbc.update("UPDATE collector_nodes SET token_hash=? WHERE id=?",NodeTokens.digest(token),f.node);nodes=new JdbcNodeStore(f.db);identity=new NodeIdentityService(nodes,tokens,clock);service=new CollectorHeartbeatService(f.store,identity,new SharedWriteExecutor(new JdbcSharedWriteEntry(f.db),new DataSourceTransactionManager(f.db)),clock);}
 @AfterEach void cleanup(){if(f!=null)f.cleanup();}
 byte[] raw(Instant value,long bytes){return f.body(value,bytes).canonical().getBytes(java.nio.charset.StandardCharsets.UTF_8);}
 @Test void actualCurrentBearerAndSharedWriterStoreOriginalHeartbeatAndReplayOldTime(){var original=service.submit(token,raw(f.now,10));at.set(f.now.plusSeconds(600));assertEquals(original,service.submit(token,raw(f.now,10)));assertEquals(f.now,original.receivedAt());assertEquals(1L,f.tx.execute(s->f.store.latest(f.node,1)).revision());assertEquals(f.now,nodes.byTokenHash(NodeTokens.digest(token)).lastSeenAt());}
 @Test void nativeRevocationOrPermissionRemovalPreventsEvenAnOriginalAck(){var body=raw(f.now,10);service.submit(token,body);assertEquals(1,nodes.setPermissions(f.node,1,"[]","[]"));assertThrows(IdentityService.Rejected.class,()->service.submit(token,body));assertEquals(1L,f.tx.execute(s->f.store.latest(f.node,1)).revision());f.jdbc.update("UPDATE collector_nodes SET enabled=0 WHERE id=?",f.node);assertThrows(IdentityService.Rejected.class,()->service.submit(token,body));}
 @Test void nativeConcurrentRequestsCommitOnlyOneHistoryAndOneOriginalAck()throws Exception{var raw=raw(f.now,10);var pool=Executors.newFixedThreadPool(2);var ready=new CountDownLatch(1);Callable<com.lianxibu.site.repository.jobs.JdbcCollectorHeartbeats.Entry> work=()->{assertTrue(ready.await(5,TimeUnit.SECONDS));return service.submit(token,raw);};try{var first=pool.submit(work);var second=pool.submit(work);ready.countDown();assertEquals(first.get(10,TimeUnit.SECONDS),second.get(10,TimeUnit.SECONDS));assertEquals(1L,f.tx.execute(s->f.store.latest(f.node,1)).revision());}finally{pool.shutdownNow();}}
 @Test void futureStaleIncompleteOrUnauthorizedFactsCannotRefreshNode(){assertThrows(IllegalArgumentException.class,()->service.submit(token,raw(f.now.plusSeconds(1),10)));assertThrows(IllegalArgumentException.class,()->service.submit(token,raw(f.now.minusSeconds(120).minusNanos(1000),10)));assertThrows(IllegalArgumentException.class,()->service.submit(token,"{}".getBytes(java.nio.charset.StandardCharsets.UTF_8)));assertThrows(IdentityService.Rejected.class,()->service.submit("fictional-invalid-token",raw(f.now,10)));assertNull(f.tx.execute(s->f.store.latest(f.node,1)));assertNull(nodes.byTokenHash(NodeTokens.digest(token)).lastSeenAt());}
 @Test void actualOuterTransactionRejectsAndSameOriginalTimeDifferentBodyCannotOverwrite(){assertThrows(IllegalStateException.class,()->f.tx.execute(s->service.submit(token,raw(f.now,10))));assertNull(f.tx.execute(s->f.store.latest(f.node,1)));service.submit(token,raw(f.now,10));assertThrows(IllegalStateException.class,()->service.submit(token,raw(f.now,11)));assertEquals(10,f.tx.execute(s->f.store.latest(f.node,1)).latest().input().sample().outboxBytes());}
}
